{
  "strategies": [
    {
      "id": "immediate",
      "label": "Immediate",
      "family": "baseline",
      "description": "Charge at available charger power.",
      "research_url": null,
      "implementation": "existing controller",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": ""
    },
    {
      "id": "fixed_delay",
      "label": "Fixed delay",
      "family": "baseline",
      "description": "Wait until the configured start hour.",
      "research_url": null,
      "implementation": "existing controller",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": ""
    },
    {
      "id": "randomized_delay",
      "label": "Randomized delay",
      "family": "baseline",
      "description": "Stagger starts using seeded delays.",
      "research_url": null,
      "implementation": "existing controller",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": ""
    },
    {
      "id": "capacity_aware",
      "label": "Capacity aware",
      "family": "heuristic",
      "description": "Departure-first allocation within capacity budgets and AC checks.",
      "research_url": null,
      "implementation": "existing controller",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": ""
    },
    {
      "id": "least_laxity_first",
      "label": "Least laxity first",
      "family": "heuristic",
      "description": "Allocate headroom to sessions with the least time slack.",
      "research_url": "https://arxiv.org/abs/2102.08610",
      "implementation": "planning-model adaptation",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": "Plain LLF, not the cited smoothed LLF algorithm."
    },
    {
      "id": "valley_filling",
      "label": "Valley filling",
      "family": "optimization",
      "description": "Coordinate-descent water filling flattens forecast demand for connected sessions.",
      "research_url": "https://smart.caltech.edu/papers/ContinuousEVCharging.pdf",
      "implementation": "planning-model adaptation",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "explicit causal persistence or previous-day baseline; no future arrivals",
      "limitation": "Finite coordinate-descent iterations; no optimality guarantee; current action projected to capacity budgets."
    },
    {
      "id": "mpc",
      "label": "Model predictive control",
      "family": "optimization",
      "description": "Re-solve a capacity-constrained linear program; prioritize energy delivery, then peak.",
      "research_url": "https://ieeexplore.ieee.org/document/9409126",
      "implementation": "planning-model adaptation",
      "action_space": "continuous_kw",
      "observations": "current connected sessions and grid state",
      "forecast": "explicit causal persistence or previous-day baseline; no future arrivals",
      "limitation": "Finite-horizon approximation with reported LLF fallback; AC feasibility checked after action."
    },
    {
      "id": "voltage_responsive",
      "label": "Voltage responsive",
      "family": "local_feedback",
      "description": "Use previous measured block voltage with gradual recovery.",
      "research_url": "https://www.sciencedirect.com/science/article/pii/S0378779618301020",
      "implementation": "planning-model adaptation",
      "action_space": "continuous_kw",
      "observations": "previous measured block voltage",
      "forecast": "none",
      "limitation": "Balanced MV block voltage, not physical charger/LV voltage. Central safety overlay may intervene."
    },
    {
      "id": "rl",
      "label": "Learned on/off policy",
      "family": "reinforcement_learning",
      "description": "A frozen trained model chooses per-session on/off actions.",
      "research_url": null,
      "implementation": "existing controller",
      "action_space": "binary_on_off",
      "observations": "current connected sessions and grid state",
      "forecast": "none",
      "limitation": ""
    }
  ],
  "commands": [
    "PROPOSE",
    "SPECIFY",
    "BUILD",
    "COMPARE",
    "CHALLENGE",
    "REVISE"
  ],
  "command_schema": {
    "$defs": {
      "ResearchReference": {
        "additionalProperties": false,
        "properties": {
          "title": {
            "maxLength": 500,
            "minLength": 1,
            "title": "Title",
            "type": "string"
          },
          "url": {
            "maxLength": 2000,
            "pattern": "^https?://",
            "title": "Url",
            "type": "string"
          },
          "mechanism": {
            "maxLength": 3000,
            "minLength": 1,
            "title": "Mechanism",
            "type": "string"
          },
          "difference": {
            "maxLength": 3000,
            "minLength": 1,
            "title": "Difference",
            "type": "string"
          }
        },
        "required": [
          "title",
          "url",
          "mechanism",
          "difference"
        ],
        "title": "ResearchReference",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "properties": {
      "command": {
        "enum": [
          "PROPOSE",
          "SPECIFY",
          "BUILD",
          "COMPARE",
          "CHALLENGE",
          "REVISE"
        ],
        "title": "Command",
        "type": "string"
      },
      "name": {
        "anyOf": [
          {
            "pattern": "^[a-z][a-z0-9_]{0,63}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Name"
      },
      "based_on": {
        "anyOf": [
          {
            "pattern": "^strategy-[a-f0-9]{20}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Based On"
      },
      "idea": {
        "anyOf": [
          {
            "maxLength": 6000,
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Idea"
      },
      "objective": {
        "anyOf": [
          {
            "maxLength": 3000,
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Objective"
      },
      "information": {
        "anyOf": [
          {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Information"
      },
      "constraints": {
        "anyOf": [
          {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Constraints"
      },
      "algorithm": {
        "anyOf": [
          {
            "maxLength": 12000,
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Algorithm"
      },
      "fallback": {
        "anyOf": [
          {
            "maxLength": 3000,
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Fallback"
      },
      "research": {
        "anyOf": [
          {
            "enum": [
              "reproduction",
              "adaptation",
              "new_hypothesis"
            ],
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Research"
      },
      "references": {
        "anyOf": [
          {
            "items": {
              "$ref": "#/$defs/ResearchReference"
            },
            "maxItems": 20,
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "References"
      },
      "parameters": {
        "additionalProperties": true,
        "title": "Parameters",
        "type": "object"
      },
      "candidates": {
        "anyOf": [
          {
            "items": {
              "type": "string"
            },
            "maxItems": 9,
            "minItems": 1,
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Candidates"
      },
      "scenario": {
        "anyOf": [
          {
            "pattern": "^exp-[a-f0-9]{20}$",
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Scenario"
      },
      "seeds": {
        "anyOf": [
          {
            "items": {
              "type": "integer"
            },
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Seeds"
      },
      "variations": {
        "anyOf": [
          {
            "items": {
              "additionalProperties": true,
              "type": "object"
            },
            "maxItems": 12,
            "minItems": 1,
            "type": "array"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Variations"
      },
      "max_cases": {
        "default": 20,
        "maximum": 100,
        "minimum": 1,
        "title": "Max Cases",
        "type": "integer"
      },
      "max_runtime_seconds": {
        "default": 300,
        "exclusiveMinimum": 0,
        "maximum": 3600,
        "title": "Max Runtime Seconds",
        "type": "number"
      }
    },
    "required": [
      "command"
    ],
    "title": "StrategyCommand",
    "type": "object"
  },
  "options_schema": {
    "additionalProperties": false,
    "properties": {
      "horizon_steps": {
        "default": 96,
        "maximum": 192,
        "minimum": 1,
        "title": "Horizon Steps",
        "type": "integer"
      },
      "forecast": {
        "default": "persistence",
        "enum": [
          "persistence",
          "previous_day"
        ],
        "title": "Forecast",
        "type": "string"
      },
      "valley_iterations": {
        "default": 8,
        "maximum": 50,
        "minimum": 1,
        "title": "Valley Iterations",
        "type": "integer"
      },
      "max_variables": {
        "default": 30000,
        "maximum": 100000,
        "minimum": 100,
        "title": "Max Variables",
        "type": "integer"
      },
      "solver_seconds": {
        "default": 3.0,
        "exclusiveMinimum": 0,
        "maximum": 30,
        "title": "Solver Seconds",
        "type": "number"
      },
      "voltage_stop_pu": {
        "default": 0.95,
        "exclusiveMinimum": 0,
        "maximum": 1.1,
        "title": "Voltage Stop Pu",
        "type": "number"
      },
      "voltage_full_pu": {
        "default": 0.99,
        "exclusiveMinimum": 0,
        "maximum": 1.2,
        "title": "Voltage Full Pu",
        "type": "number"
      },
      "recovery_fraction": {
        "default": 0.25,
        "exclusiveMinimum": 0,
        "maximum": 1,
        "title": "Recovery Fraction",
        "type": "number"
      }
    },
    "title": "StrategyOptions",
    "type": "object"
  },
  "records": [],
  "build_contract": "BUILD prepares a coding handoff. It never runs arbitrary submitted code or claims tests passed. Codex implements through the workspace, then the live registry establishes availability.",
  "example": "STRATEGY PROPOSE\nname: deadline_headroom\nidea: Allocate headroom by energy urgency.\nobjective: Meet departures within network capacity.\nresearch: adaptation"
}

